<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Consent\Domain\PendingConsentRequest;
use Civi\Lughauth\Features\OAuth\Consent\Domain\ScopePermission;
use Civi\Lughauth\Features\OAuth\Consent\Domain\TermsOfUseAcceptance;
use Civi\Lughauth\Features\OAuth\Consent\Domain\GdprConsentPurposeItem;
use Civi\Lughauth\Features\OAuth\Consent\Application\Usecase\ConsentOrchestration\EnqueueConsentParams;
use Civi\Lughauth\Features\OAuth\Consent\Application\Usecase\ConsentOrchestration\NextConsentResult;

final class ConsentDomainUnitTest extends TestCase
{
    // --- PendingConsentRequest ---

    public function test_pending_consent_request_stores_fields(): void
    {
        $at = new DateTimeImmutable('2026-01-01');
        $req = new PendingConsentRequest('u1', 't1', 'c1', 'https://cb', 'openid profile', $at);

        $this->assertSame('u1', $req->userId);
        $this->assertSame('t1', $req->tenant);
        $this->assertSame('c1', $req->clientId);
        $this->assertSame('https://cb', $req->redirectUri);
        $this->assertSame('openid profile', $req->scope);
        $this->assertSame($at, $req->createdAt);
    }

    public function test_pending_consent_request_create_factory(): void
    {
        $before = new DateTimeImmutable();
        $req = PendingConsentRequest::create('u', 't', 'c', 'https://cb', 'openid email');
        $after = new DateTimeImmutable();

        $this->assertGreaterThanOrEqual($before->getTimestamp(), $req->createdAt->getTimestamp());
        $this->assertLessThanOrEqual($after->getTimestamp(), $req->createdAt->getTimestamp());
    }

    public function test_scope_list_splits_by_space(): void
    {
        $req = PendingConsentRequest::create('u', 't', 'c', 'https://cb', 'openid profile email');
        $this->assertSame(['openid', 'profile', 'email'], $req->scopeList());
    }

    public function test_scope_list_filters_empty_segments(): void
    {
        $req = PendingConsentRequest::create('u', 't', 'c', 'https://cb', '');
        $this->assertSame([], $req->scopeList());
    }

    // --- ScopePermission ---

    public function test_scope_permission_stores_fields(): void
    {
        $sp = new ScopePermission('api:read', true, 'Read API', 'Allows reading data');
        $this->assertSame('api:read', $sp->scope);
        $this->assertTrue($sp->required);
        $this->assertSame('Read API', $sp->label);
    }

    public function test_display_label_uses_label_when_set(): void
    {
        $sp = new ScopePermission('api:read', false, 'Custom Label');
        $this->assertSame('Custom Label', $sp->displayLabel());
    }

    public function test_display_label_derives_from_scope_when_label_null(): void
    {
        $sp = new ScopePermission('api_read', false);
        $this->assertSame('API READ', $sp->displayLabel());
    }

    public function test_display_label_derives_from_scope_when_label_empty(): void
    {
        $sp = new ScopePermission('my-scope', false, '');
        $this->assertSame('MY SCOPE', $sp->displayLabel());
    }

    // --- TermsOfUseAcceptance ---

    public function test_terms_of_use_acceptance_stores_fields(): void
    {
        $t = new TermsOfUseAcceptance('tos-1', 'By using this service you agree...');
        $this->assertSame('tos-1', $t->id);
        $this->assertSame('By using this service you agree...', $t->text);
    }

    // --- GdprConsentPurposeItem ---

    public function test_gdpr_consent_purpose_item_stores_fields(): void
    {
        $item = new GdprConsentPurposeItem('uid-1', 'marketing', 'Marketing', 'We use your data for ads', false);
        $this->assertSame('uid-1', $item->uid);
        $this->assertSame('marketing', $item->key);
        $this->assertSame('Marketing', $item->title);
        $this->assertFalse($item->required);
    }

    // --- EnqueueConsentParams ---

    public function test_enqueue_consent_params_stores_fields(): void
    {
        $p = new EnqueueConsentParams('u', 't', 'c', 'https://cb', 'openid');
        $this->assertSame('u', $p->userId);
        $this->assertSame('t', $p->tenant);
        $this->assertSame('c', $p->clientId);
        $this->assertSame('https://cb', $p->redirectUri);
        $this->assertSame('openid', $p->scope);
    }

    // --- NextConsentResult ---

    public function test_next_consent_result_has_pending_when_next_not_null(): void
    {
        $pending = PendingConsentRequest::create('u', 't', 'c', 'https://cb', 'openid');
        $r = new NextConsentResult($pending, 3);

        $this->assertTrue($r->hasPending());
        $this->assertSame($pending, $r->next);
        $this->assertSame(3, $r->remaining);
    }

    public function test_next_consent_result_no_pending_when_next_null(): void
    {
        $r = new NextConsentResult(null, 0);
        $this->assertFalse($r->hasPending());
    }
}
